using Meziantou.Framework.WebPlatform.Css.Cascade;
using Meziantou.Framework.WebPlatform.Dom;

namespace Meziantou.Framework.WebPlatform.Css.Layout;

/// <summary>
/// A box of the box tree (https://drafts.csswg.org/css-display/#box-tree): a <see cref="ContainerBox"/> (the boxes
/// generated by the elements, the pseudo-elements and the anonymous boxes) or a <see cref="TextRun"/>.
/// </summary>
/// <remarks>
/// The boxes are created by <see cref="BoxTreeBuilder"/>. The tree is immutable for the layout: the formatting contexts
/// attach their per-box state to <see cref="LayoutState"/> and read the structure.
/// </remarks>
internal abstract class LayoutBox
{
    private protected LayoutBox(ComputedStyle style, Display display, Element? element, string? pseudoElement)
    {
        Style = style;
        Display = display;
        Element = element;
        PseudoElement = pseudoElement;
    }

    /// <summary>
    /// The style of the box: the computed style of its element or pseudo-element, the style of the parent of a text node,
    /// or for an anonymous box a style that inherits from its parent box (the non-inherited properties have their initial
    /// value, https://drafts.csswg.org/css-display/#anonymous).
    /// </summary>
    public ComputedStyle Style { get; internal set; }

    /// <summary>
    /// The used display type of the box: the computed value of its element after the box tree fixups (e.g. a run-in box
    /// inserted in a block is inline, a block-level child of a ruby container is inlinified), or the display type of an
    /// anonymous box. A text run is inline.
    /// </summary>
    public Display Display { get; internal set; }

    /// <summary>
    /// The element that generates the box: the element of a principal box, the originating element of a pseudo-element box
    /// (see <see cref="PseudoElement"/>), the parent element of a text node, or null for an anonymous box and the viewport.
    /// </summary>
    public Element? Element { get; }

    /// <summary>The pseudo-element that generates the box (<c>before</c>, <c>after</c>, <c>marker</c>, <c>first-letter</c>), or null.</summary>
    public string? PseudoElement { get; }

    public ContainerBox? Parent { get; internal set; }

    public LayoutBox? PreviousSibling { get; internal set; }

    public LayoutBox? NextSibling { get; internal set; }

    /// <summary>
    /// The state of the layout attached to the box by its formatting context (e.g. cached intrinsic sizes). It is owned by
    /// the layout pass and reset when the box tree is rebuilt.
    /// </summary>
    public object? LayoutState { get; set; }

    /// <summary>
    /// The first fragment generated by the box in the fragment tree of the last layout (the next ones are linked by
    /// <see cref="Fragment.NextFragmentOfBox"/>), valid when <see cref="FragmentIndexVersion"/> is the version of the fragment
    /// index of the <see cref="LayoutEngine"/> (see <see cref="LayoutEngine.GetFragments(Element, string?)"/>).
    /// </summary>
    internal Fragment? FirstFragment { get; set; }

    /// <summary>The last fragment generated by the box in the fragment tree of the last layout.</summary>
    internal Fragment? LastFragment { get; set; }

    /// <summary>The version of the fragment index of the layout engine <see cref="FirstFragment"/> was set for.</summary>
    internal int FragmentIndexVersion { get; set; }

    /// <summary>Whether the box is inline-level (https://drafts.csswg.org/css-display/#inline-level), text runs included.</summary>
    public bool IsInlineLevel => Display.IsInlineLevel;

    /// <summary>Whether the box is block-level (https://drafts.csswg.org/css-display/#block-level).</summary>
    public bool IsBlockLevel => Display.IsBlockLevel;

    /// <summary>
    /// Whether the box is out of flow (https://drafts.csswg.org/css-display/#out-of-flow): absolutely positioned (including the
    /// boxes rendered in the top layer), or floating in a block or inline formatting context (the float property does not apply
    /// to the flex and grid items). The table grid box of a positioned or floating table is in the flow of its table wrapper box.
    /// </summary>
    public bool IsOutOfFlow
    {
        get
        {
            if (this is not ContainerBox { IsAnonymous: false } container || container.Kind == ContainerBoxKind.TableGrid)
                return false;

            if (container.IsInTopLayer)
                return true;

            var layout = Style.Layout;
            if (layout.IsAbsolutelyPositioned)
                return true;

            return layout.IsFloating && (Parent is null || !Parent.EstablishesIndependentChildrenLayout);
        }
    }

    /// <summary>Whether the box is in normal flow: not out of flow.</summary>
    public bool IsInFlow => !IsOutOfFlow;

    /// <summary>Whether the box is an anonymous box (https://drafts.csswg.org/css-display/#anonymous).</summary>
    public virtual bool IsAnonymous => false;
}

/// <summary>The kinds of <see cref="ContainerBox"/>.</summary>
internal enum ContainerBoxKind : byte
{
    /// <summary>The root of the box tree: the initial containing block (https://drafts.csswg.org/css-display/#initial-containing-block), whose child is the principal box of the root element.</summary>
    Viewport,

    /// <summary>A box generated by an element or a pseudo-element whose layout is given by its display type (a block, an inline box, a flex container...).</summary>
    Normal,

    /// <summary>
    /// An atomic box whose content is outside of the CSS formatting model: a replaced element, a form control, an outermost
    /// svg element, or an image of the generated content (see <see cref="ContainerBox.GeneratedImage"/>). It has no children,
    /// except the <c>foreignObject</c> boxes of an svg element, the boxes of the cues of a video element and the inner editor
    /// or the placeholder of a text control (see <see cref="TextControlLayout"/>).
    /// </summary>
    Replaced,

    /// <summary>
    /// A table wrapper box (https://drafts.csswg.org/css-tables-3/#table-wrapper-box): the principal box of a table, a block
    /// container (block-level or inline-level) whose children are the table grid box and the captions.
    /// </summary>
    TableWrapper,

    /// <summary>A table grid box (https://drafts.csswg.org/css-tables-3/#table-grid-box): the child of a table wrapper box, whose children are the row groups, the rows, the columns and the column groups.</summary>
    TableGrid,

    /// <summary>An anonymous box generated by the fixups (https://drafts.csswg.org/css-display/#anonymous): a block, a table part, a ruby part.</summary>
    Anonymous,
}

/// <summary>
/// A box that can contain other boxes: the box of an element or pseudo-element, an anonymous box, or the viewport.
/// </summary>
internal sealed class ContainerBox : LayoutBox
{
    internal ContainerBox(ContainerBoxKind kind, ComputedStyle style, Display display, Element? element, string? pseudoElement = null)
        : base(style, display, element, pseudoElement)
    {
        Kind = kind;
    }

    /// <summary>The properties that few boxes have (allocated on first use).</summary>
    private RareData? _rareData;

    public ContainerBoxKind Kind { get; }

    /// <summary>The fragment of the last layout of the box (<see cref="LayoutContext.LayoutBox"/>), for the anchor queries (see <see cref="BoxFragment.LayoutPass"/>).</summary>
    internal BoxFragment? LastLayoutFragment { get; set; }

    public override bool IsAnonymous => Element is null && Kind != ContainerBoxKind.Viewport;

    public LayoutBox? FirstChild { get; private set; }

    public LayoutBox? LastChild { get; private set; }

    /// <summary>Whether the box has no child box.</summary>
    public bool IsEmpty => FirstChild is null;

    /// <summary>
    /// Whether the in-flow children of the box are inline-level (text runs, inline boxes, atomic inlines): the box
    /// establishes an inline formatting context or continues the one of its parent. The children of a block container are
    /// either all inline-level or all block-level (https://drafts.csswg.org/css-display/#block-container); out-of-flow boxes
    /// and an outside <c>::marker</c> may be mixed with both.
    /// </summary>
    public bool ChildrenAreInline { get; internal set; }

    /// <summary>
    /// The next part of an inline box split around block-level boxes (https://drafts.csswg.org/css2/#anonymous-block-level):
    /// the parts have the same element and style; the first part is the principal box of the element, its start edges
    /// (margin, border, padding) are on the first part and its end edges on the last part.
    /// </summary>
    public ContainerBox? Continuation { get => _rareData?.Continuation; internal set => GetRareData().Continuation = value; }

    /// <summary>The previous part of an inline box split around block-level boxes, or null for the first part.</summary>
    public ContainerBox? PreviousContinuation { get => _rareData?.PreviousContinuation; internal set => GetRareData().PreviousContinuation = value; }

    /// <summary>
    /// Whether the box skips its contents (https://drafts.csswg.org/css-contain-2/#skips-its-contents): <c>content-visibility:
    /// hidden</c>, <c>content-visibility: auto</c> when the element is not relevant to the user (<see cref="IsContentVisibilityAuto"/>,
    /// updated before each layout pass by <see cref="ContentRelevancy"/>), or a closed <c>details</c> element (the boxes of its
    /// contents but its summary). The boxes of the contents are generated, but they are not laid out (the box has size
    /// containment, unless a geometry API needs them: <see cref="LaysOutSkippedContents"/>), painted or hit tested.
    /// </summary>
    public bool SkipsContents { get; internal set; }

    /// <summary>
    /// Whether the box is the principal box of an element with <c>content-visibility: auto</c> (when it applies to the box, see
    /// <see cref="UsedContainment.CanApplySizeContainment(ContainerBox)"/>): it skips its contents when the element is not
    /// relevant to the user (https://drafts.csswg.org/css-contain-2/#relevant-to-the-user).
    /// </summary>
    public bool IsContentVisibilityAuto { get => _rareData?.IsContentVisibilityAuto ?? false; internal set => GetRareData().IsContentVisibilityAuto = value; }

    /// <summary>
    /// Whether the skipped contents of the box are laid out (but still not painted nor hit tested): a geometry API needed the
    /// layout of a box in them (https://drafts.csswg.org/css-contain-2/#cv-examples: "the user-agent cannot avoid rendering
    /// work"), see <see cref="LayoutEngine.GetFragments"/>. The layout engine sets it again when the box tree is built again,
    /// until the next rendering update.
    /// </summary>
    public bool LaysOutSkippedContents { get => _rareData?.LaysOutSkippedContents ?? false; internal set => GetRareData().LaysOutSkippedContents = value; }

    /// <summary>Whether the contents of the box are not laid out: it skips its contents, and no geometry API needed them.</summary>
    public bool HasUnlaidSkippedContents => SkipsContents && !LaysOutSkippedContents;

    /// <summary>
    /// The style of the <c>::first-line</c> pseudo-element (https://drafts.csswg.org/css-pseudo-4/#first-line-pseudo) of a
    /// block container whose style sheets may style it, or null. It is not a box: the inline layout applies it to the first
    /// formatted line.
    /// </summary>
    public ComputedStyle? FirstLineStyle { get => _rareData?.FirstLineStyle; internal set => GetRareData().FirstLineStyle = value; }

    /// <summary>
    /// The inline box a block-level or out-of-flow box was split out of (https://drafts.csswg.org/css2/#anonymous-block-level):
    /// a box between the parts of an inline box split around block-level boxes is a child of the block container, but the
    /// relative offsets of the inline box (and of its inline ancestors) move it, and the inline box is its containing block
    /// when it is positioned (see <see cref="PositionedLayout.GetPositioningParent"/>). Null for the other boxes.
    /// </summary>
    public ContainerBox? SplitInlineParent { get => _rareData?.SplitInlineParent; internal set => GetRareData().SplitInlineParent = value; }

    /// <summary>
    /// Whether the box is rendered in the top layer (https://drafts.csswg.org/css-position-4/#top-layer): the box of an element
    /// of the top layer of the document, or its <c>::backdrop</c>. It is a child of the viewport box, after the root box, in the
    /// order of the top layer, and it is absolutely positioned (fixed when its position is fixed).
    /// </summary>
    public bool IsInTopLayer { get; internal set; }

    /// <summary>
    /// Whether the box is the box of the <c>::view-transition</c> pseudo-element of the document element
    /// (https://drafts.csswg.org/css-view-transitions-1/#view-transition-painting-order): the view transition layer, a child of the
    /// viewport box painted after the top layer, whose containing block is the snapshot containing block (it does not scroll
    /// with the viewport, https://drafts.csswg.org/css-view-transitions-1/#snapshot-containing-block).
    /// </summary>
    public bool IsViewTransitionRoot { get; internal set; }

    /// <summary>
    /// Whether the box is the box of the <c>::view-transition</c> pseudo-element of a scoped view transition
    /// (https://drafts.csswg.org/css-view-transitions-2/#scoped-vt-layout): the last child of the box of the root element of the
    /// transition, absolutely positioned in its padding box. It "generates a stacking context which paints separately from, and
    /// on top of, the painting of the root element and its other children" (the effects of the root element do not apply to it,
    /// its transform does), "is not translated by the scroll position of the root element", "is exempted from [its] clip", and
    /// does not extend its scrollable overflow.
    /// </summary>
    public bool IsScopedViewTransitionRoot { get; internal set; }

    /// <summary>Whether the box stays in place when the viewport scrolls: a fixed positioned box, or the view transition layer.</summary>
    public bool IsFixedToViewport => IsViewTransitionRoot || Style.Layout.Position == PositionKind.Fixed;

    /// <summary>The image of a box of the generated content (<c>content: url(...)</c>, a <c>list-style-image</c> marker): a computed &lt;image&gt; value, or null.</summary>
    public string? GeneratedImage { get => _rareData?.GeneratedImage; internal set => GetRareData().GeneratedImage = value; }

    /// <summary>
    /// The values of the initial letter when the box is an initial letter box (https://drafts.csswg.org/css-inline-3/#initial-letter-styling):
    /// a <c>::first-letter</c> box whose <c>initial-letter</c> is not <c>normal</c>, placed by the inline layout, or null.
    /// </summary>
    public InitialLetterBox? InitialLetter { get => _rareData?.InitialLetter; internal set => GetRareData().InitialLetter = value; }

    /// <summary>
    /// The state of a layout API container (https://drafts.css-houdini.org/css-layout-api-1/#layout-api-container): a box whose
    /// display is <c>layout(name)</c> and whose layout is registered in the layout worklet of the document. It is laid out by
    /// <see cref="LayoutApiFormattingContext"/>, and its in-flow children establish independent formatting contexts. Null for
    /// the other boxes: a box whose layout is not registered is a flow-root block container.
    /// </summary>
    public Dom.LayoutApiContainer? LayoutApi { get => _rareData?.LayoutApi; internal set => GetRareData().LayoutApi = value; }

    /// <summary>Whether the box is an outside <c>::marker</c> (https://drafts.csswg.org/css-lists-3/#outside): it is positioned by the layout outside of the principal box of its list item.</summary>
    public bool IsOutsideMarker { get; internal set; }

    /// <summary>
    /// Whether the box is an anonymous ruby base or ruby annotation that wraps intra-level white space
    /// (https://drafts.csswg.org/css-ruby-1/#anon-gen-interpret-space): the white space between two ruby bases or between two
    /// ruby annotations of a level. The ruby layout pairs the white space of the levels with each other (see
    /// <see cref="InlineLayoutAlgorithm"/>).
    /// </summary>
    public bool IsRubyWhiteSpace { get; internal set; }

    /// <summary>
    /// Whether the box is the anonymous fieldset content box of a fieldset
    /// (https://html.spec.whatwg.org/multipage/rendering.html#anonymous-fieldset-content-box): it holds the contents of the
    /// fieldset other than its rendered legend, with the paddings, the overflow and the inner display of the fieldset.
    /// </summary>
    public bool IsFieldsetContent { get; internal set; }

    /// <summary>
    /// Whether the box is the inner editor of a text control (see <see cref="TextControlLayout"/>): the anonymous block
    /// container of the value of a <c>textarea</c> or of a text field, a child of the replaced box of the control. The inner
    /// editor of a text field is the scroll container of its value.
    /// </summary>
    public bool IsTextControlInnerEditor { get; internal set; }

    /// <summary>
    /// Whether the box is the anonymous block container of the contents of a form control that is a replaced box (see
    /// <see cref="FormControlContents"/>): the options of a list box with native appearance, the parts of a slider or of a
    /// file upload control. It is laid out in the content box of the control.
    /// </summary>
    public bool IsFormControlContents { get; internal set; }

    /// <summary>
    /// The element whose scrolling box the box is when it is a scroll container: its element; the fieldset of an anonymous
    /// fieldset content box (the <c>overflow</c> of a fieldset applies to its content box); the text field of an inner editor
    /// (its value scrolls in its inner editor). Null for the other anonymous boxes and for the boxes of the pseudo-elements.
    /// </summary>
    /// <remarks>
    /// The select popover of a select element (the box of its <c>::picker(select)</c> pseudo-element, which scrolls its
    /// options) has the scroll state of the select element, whose own box, a button, does not scroll.
    /// </remarks>
    internal Element? ScrollingElement => PseudoElement is not null
        ? (PseudoElement == Cascade.StyleEngine.SelectPicker ? Element : null)
        : Element ?? (IsFieldsetContent || IsTextControlInnerEditor ? Style.Element : null);

    /// <summary>The cache of the intrinsic inline sizes of the box for a layout pass (see <see cref="IntrinsicSizing.GetIntrinsicInlineSizes"/>), or null.</summary>
    internal IntrinsicSizesCache? IntrinsicSizesCache { get; set; }

    /// <summary>
    /// The layout pass that last asked for the scrollbar gutters of the box to size it from its contents, before its layout
    /// (<see cref="IntrinsicSizing.GetScrollbarGutters"/>), and the scrollbars that were assumed (see <see cref="LayoutEngine.UpdateLayout"/>).
    /// </summary>
    internal int ScrollbarGuttersPass { get; set; }

    /// <summary>The scrollbars assumed by the layout pass <see cref="ScrollbarGuttersPass"/>.</summary>
    internal Scrollbars AssumedScrollbars { get; set; }

    /// <summary>The last measure of the intrinsic block size of the box in the layout pass (see <see cref="LayoutContext.MeasureIntrinsicBlockSize"/>), or null.</summary>
    internal IntrinsicBlockSizeCache? IntrinsicBlockSizeCache { get; set; }

    /// <summary>The result of the last layout of the box, used again by the next layout passes that lay it out in the same constraint space (see <see cref="LayoutResultCache"/>), or null.</summary>
    internal LayoutResultCacheEntry? LayoutResult { get; set; }

    /// <summary>The result of the last layout of the box that measured its intrinsic block size (see <see cref="ConstraintSpace.MeasuresIntrinsicBlockSize"/>, <see cref="LayoutResultCache"/>), or null.</summary>
    internal LayoutResultCacheEntry? MeasureLayoutResult { get; set; }

    /// <summary>
    /// Whether the children are laid out by a formatting context other than block and inline layout (flex, grid, table,
    /// math...): their floats do not float (the float property does not apply) and they are not split around block-level boxes.
    /// </summary>
    public bool EstablishesIndependentChildrenLayout => Kind is ContainerBoxKind.TableGrid or ContainerBoxKind.Replaced
        || Display.Inside is DisplayInside.Flex or DisplayInside.WebkitBox or DisplayInside.Grid or DisplayInside.GridLanes or DisplayInside.Table or DisplayInside.Math
        || Display.Internal is DisplayInternal.TableRow or DisplayInternal.TableRowGroup or DisplayInternal.TableHeaderGroup or DisplayInternal.TableFooterGroup or DisplayInternal.TableColumnGroup or DisplayInternal.TableColumn;

    /// <summary>Whether the box is a block container (https://drafts.csswg.org/css-display/#block-container): it contains block-level boxes or establishes an inline formatting context.</summary>
    public bool IsBlockContainer => Kind switch
    {
        ContainerBoxKind.Viewport or ContainerBoxKind.TableWrapper => true,
        ContainerBoxKind.Replaced or ContainerBoxKind.TableGrid => false,
        _ => Display.IsBlockContainer,
    };

    /// <summary>Whether the box is an inline box (https://drafts.csswg.org/css-display/#inline-box): a non-atomic inline-level box whose contents participate in the inline formatting context of its parent.</summary>
    public bool IsInlineBox => Kind is ContainerBoxKind.Normal or ContainerBoxKind.Anonymous && Display.IsInlineBox;

    /// <summary>Whether the box is an atomic inline (https://drafts.csswg.org/css-display/#atomic-inline): an inline-level replaced box or an inline-level box that is not an inline box.</summary>
    public bool IsAtomicInline => Display.IsInlineLevel && !IsInlineBox;

    /// <summary>Enumerates the children of the box.</summary>
    public ChildEnumerator Children => new(FirstChild);

    internal void AppendChild(LayoutBox child) => InsertBefore(child, reference: null);

    internal void InsertBefore(LayoutBox child, LayoutBox? reference)
    {
        child.Parent?.RemoveChild(child);
        child.Parent = this;
        var previous = reference is null ? LastChild : reference.PreviousSibling;
        child.PreviousSibling = previous;
        child.NextSibling = reference;
        if (previous is null)
        {
            FirstChild = child;
        }
        else
        {
            previous.NextSibling = child;
        }

        if (reference is null)
        {
            LastChild = child;
        }
        else
        {
            reference.PreviousSibling = child;
        }
    }

    internal void RemoveChild(LayoutBox child)
    {
        if (child.PreviousSibling is { } previous)
        {
            previous.NextSibling = child.NextSibling;
        }
        else
        {
            FirstChild = child.NextSibling;
        }

        if (child.NextSibling is { } next)
        {
            next.PreviousSibling = child.PreviousSibling;
        }
        else
        {
            LastChild = child.PreviousSibling;
        }

        child.Parent = null;
        child.PreviousSibling = null;
        child.NextSibling = null;
    }

    /// <summary>Removes the children and returns them in a list (the fixups rebuild the list of children).</summary>
    internal List<LayoutBox> DetachChildren(List<LayoutBox>? list = null)
    {
        list ??= [];
        for (var child = FirstChild; child is not null;)
        {
            var next = child.NextSibling;
            child.Parent = null;
            child.PreviousSibling = null;
            child.NextSibling = null;
            list.Add(child);
            child = next;
        }

        FirstChild = null;
        LastChild = null;
        return list;
    }

    private RareData GetRareData() => _rareData ??= new RareData();

    private sealed class RareData
    {
        public ContainerBox? Continuation;
        public ContainerBox? PreviousContinuation;
        public ComputedStyle? FirstLineStyle;
        public string? GeneratedImage;
        public ContainerBox? SplitInlineParent;
        public bool IsContentVisibilityAuto;
        public bool LaysOutSkippedContents;
        public InitialLetterBox? InitialLetter;
        public Dom.LayoutApiContainer? LayoutApi;
    }

    /// <summary>Enumerates the children of a box without allocation.</summary>
    public struct ChildEnumerator(LayoutBox? first)
    {
        private LayoutBox? _next = first;

        public LayoutBox Current { get; private set; } = null!;

        public readonly ChildEnumerator GetEnumerator() => this;

        public bool MoveNext()
        {
            if (_next is null)
                return false;

            Current = _next;
            _next = _next.NextSibling;
            return true;
        }
    }
}

/// <summary>The kinds of <see cref="TextRun"/>.</summary>
internal enum TextRunKind : byte
{
    /// <summary>The text of a DOM text node (<see cref="TextRun.Node"/>).</summary>
    Text,

    /// <summary>A text of the generated content (the strings, counters and quotes of <c>content</c>, the text of a <c>::marker</c>).</summary>
    Generated,

    /// <summary>The forced line break of a <c>br</c> element: a preserved U+000A (https://html.spec.whatwg.org/multipage/rendering.html#phrasing-content-3).</summary>
    LineBreak,

    /// <summary>The line break opportunity of a <c>wbr</c> element: a U+200B ZERO WIDTH SPACE.</summary>
    WordBreakOpportunity,
}

/// <summary>
/// A run of text: the text of a DOM text node (or of a part of it, e.g. when its first letter is in a <c>::first-letter</c>
/// box), or a text of the generated content. A text run is the anonymous inline box of the text that is directly contained
/// in a block container (https://drafts.csswg.org/css2/#anonymous); its style is the style of its parent element (or
/// pseudo-element). The white space processing is done by the inline layout: the text is the raw text.
/// </summary>
internal sealed class TextRun : LayoutBox
{
    internal TextRun(ComputedStyle style, Element? element, string? pseudoElement, TextRunKind kind, Text? node, string data, int start, int length)
        : base(style, Display.Inline, element, pseudoElement)
    {
        Kind = kind;
        Node = node;
        Data = data;
        Start = start;
        Length = length;
    }

    public TextRunKind Kind { get; }

    /// <summary>The DOM text node of the run (<see cref="TextRunKind.Text"/>), or null for a generated text.</summary>
    public Text? Node { get; }

    /// <summary>
    /// The string the run is a part of: the data of the text node when the box tree was built (the box tree is rebuilt when
    /// the DOM changes), or the generated text.
    /// </summary>
    public string Data { get; }

    /// <summary>The offset of the run in <see cref="Data"/> (the offset in the text node, in UTF-16 code units).</summary>
    public int Start { get; internal set; }

    /// <summary>The length of the run in UTF-16 code units.</summary>
    public int Length { get; internal set; }

    /// <summary>The end offset of the run in <see cref="Data"/>.</summary>
    public int End => Start + Length;

    /// <summary>The next run of the same text node (e.g. the rest of the text after a <c>::first-letter</c>), or null.</summary>
    public TextRun? NextRunOfNode { get; internal set; }

    /// <summary>The characters of the run.</summary>
    public ReadOnlySpan<char> Text => Data.AsSpan(Start, Length);

    /// <summary>
    /// Whether the run contains only white space characters (spaces, tabs, segment breaks, https://drafts.csswg.org/css-text/#white-space)
    /// that are collapsible: they are removed by the white space processing when they are at the start or at the end of a line.
    /// </summary>
    public bool IsCollapsibleWhiteSpace
    {
        get
        {
            if (Kind != TextRunKind.Text || !IsWhiteSpace(Text))
                return false;

            return Style.Layout.WhiteSpaceCollapse switch
            {
                WhiteSpaceCollapse.Collapse or WhiteSpaceCollapse.Discard => true,
                WhiteSpaceCollapse.PreserveBreaks => !Text.ContainsAny('\n', '\r'),
                _ => false,
            };
        }
    }

    /// <summary>Whether the text contains only document white space characters (https://drafts.csswg.org/css-text/#white-space): spaces, tabs, segment breaks and form feeds.</summary>
    public static bool IsWhiteSpace(ReadOnlySpan<char> text) => text.IndexOfAnyExcept(" \t\n\r\f") < 0;
}
